        this.tipo = tipo;
    }

    @Override
    public Produto getProduto() {
        if ("Livro".equals(this.tipo)) {
            return new Livro();
        } else if ("Filme".equals(this.tipo)) {
            return new Filme();
        }
        throw new IllegalArgumentException("Tipo de produto não suportado");
    }
}

public class Main {
